def added(points, p):
    """Return a new immutable set including p."""
    return points.union([p])

def repeats(path, seen=None):
    """Report repeated segments in this path or continue the supplied set."""
    if seen is None:
        seen = set()
    repeat = []
    for name in path:
        if name in seen:
            repeat.append(name)
        seen.add(name)
    return repeat

